SCH_price_markdown.invariants_dsl:
spec PriceMarkdown {
    field final_price: Number {
        value <= this.original_price;
        value >= 1.0;
    }
    field original_price: Number {
        value >= 1.0;
        value <= 1000.0;
    }
    field discount_reason: String {
        value IN ["clearance", "seasonal", "loyalty", "bulk"];
    }
}

SCH_bonus_plan.invariants_dsl:
spec SalaryInfo {
    field base_salary: Number {
        value >= 30000.0;
        value <= 300000.0;
    }
}

spec BonusPlan {
    field bonus_amount: Number {
        value <= this.salary_info.base_salary * 0.5;
        value >= 0.0;
    }
    field salary_info: SalaryInfo {
    }
    field bonus_type: String {
        value IN ["performance", "retention", "signing", "referral"];
    }
}
